test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 245000 }), 245000);
});

test('invoiceTotals sums line totals and calculates discount and total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }, { sku: 'STICKER', qty: 100 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 95000 + 5000);
  assert.equal(totals.discount, 0);
  // VAT: 95000 * 0.21 = 19950, 5000 * 0.21 = 1050, total = 21000
  assert.equal(totals.vat, 21000);
  assert.equal(totals.total, 100000 + 21000);
});

test('invoiceTotals with a single line', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 120000 * 2);
  assert.equal(totals.discount, 0);
  // VAT: 240000 * 0.21 = 50400
  assert.equal(totals.vat, 50400);
  assert.equal(totals.total, 240000 + 50400);
});

test('invoiceTotals with multiple varied lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
      { sku: 'STICKER', qty: 250 },
    ],
  });

  const totals = invoiceTotals(result.value);
  const expected = (9500 * 5) + (6000 * 3) + (50 * 250);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, 0);
  // VAT: 47500 * 0.21 = 9975, 18000 * 0.21 = 3780, 12500 * 0.21 = 2625, total = 16380
  assert.equal(totals.vat, 16380);
  assert.equal(totals.total, expected + 16380);
});

